<!-- Interactive Script for Workspace Navigation Highlighting and Dynamic State -->
<script>
    document.addEventListener('DOMContentLoaded', () => {
      // Highlight Pet Management > Intake & Health in shell aside navigation
      const navLinks = document.querySelectorAll('aside nav a');
      navLinks.forEach(link => {
        if (link.getAttribute('data-path') === 'intake-and-health-records') {
          link.classList.remove('text-on-surface-variant', 'hover:bg-surface-container-high', 'hover:text-on-surface');
          link.classList.add('bg-primary-container', 'text-on-primary-container', 'font-semibold', 'shadow-sm');
          const icon = link.querySelector('.material-symbols-outlined');
          if (icon) icon.classList.add('text-on-primary-container');
        }
      });

      // Update Shell Header Breadcrumb
      const breadcrumb = document.querySelector('header .flex.items-center.gap-space-sm');
      if (breadcrumb) {
        breadcrumb.innerHTML = `
          <span class="font-label-sm text-label-sm text-secondary uppercase font-semibold">Admin Portal</span>
          <span class="material-symbols-outlined text-[14px] text-secondary">chevron_right</span>
          <span class="font-label-sm text-label-sm text-secondary uppercase font-semibold">Pet Management</span>
          <span class="material-symbols-outlined text-[14px] text-secondary">chevron_right</span>
          <span class="font-label-sm text-label-sm text-primary font-bold">Intake &amp; Health</span>
        `;
      }
    });

    function togglePublishCatalog(checkbox) {
      const banner = document.getElementById('catalog-sync-indicator');
      const feeInput = document.getElementById('adoption-fee-container');
      if (checkbox.checked) {
        banner.classList.remove('opacity-50');
        feeInput.classList.remove('opacity-50', 'pointer-events-none');
      } else {
        banner.classList.add('opacity-50');
        feeInput.classList.add('opacity-50', 'pointer-events-none');
      }
    }
  </script>
